package cpamp

import "sort"

// Selections group retained identities without transferring ownership of events.
// Small metadata uses the existing append-only profile revision ledger.
type SubscriptionAssignment struct {
	Account string `json:"account"`
	Plan    string `json:"plan"`
	Start   int64  `json:"start_ms"`
	End     int64  `json:"end_ms"`
}

func quotaProfileContains(c ProfileConfig, p Profile, account string, at int64) bool {
	if p.Memberships != nil {
		for _, m := range p.Memberships {
			if m.Account == account && at >= m.Start && (m.End == 0 || at < m.End) {
				return true
			}
		}
		return false
	}
	if p.Selection {
		for _, id := range p.Accounts {
			if id == account {
				return true
			}
		}
		return false
	}
	return ownerAt(c, account, at) == p.ID
}

func quotaProfileAccounts(c ProfileConfig, p Profile) []string {
	set := map[string]bool{}
	if p.Memberships != nil {
		for _, m := range p.Memberships {
			set[m.Account] = true
		}
	} else if p.Selection {
		for _, a := range p.Accounts {
			set[a] = true
		}
	} else {
		if p.ActiveAccount != "" {
			set[p.ActiveAccount] = true
		}
		for _, b := range c.Bindings {
			if b.Profile == p.ID {
				set[b.Account] = true
			}
		}
	}
	out := make([]string, 0, len(set))
	for a := range set {
		out = append(out, a)
	}
	sort.Strings(out)
	return out
}
